  // ---------- motion ----------
  const SLIDE_MS = 180;
  const rookOf = m => m.flags.indexOf('k') >= 0 ? (m.color === 'w' ? ['h1', 'f1'] : ['h8', 'f8']) : m.flags.indexOf('q') >= 0 ? (m.color === 'w' ? ['a1', 'd1'] : ['a8', 'd8']) : null;
  const animOf = m => ({ from: m.from, to: m.to, cap: m.captured || null, capColor: m.color === 'w' ? 'b' : 'w', capSq: m.flags.indexOf('e') >= 0 ? m.to[0] + m.from[1] : m.to, rook: rookOf(m) });
