  // ---------- board ----------
  // Colours: light #f0e2c4 / dark #b88a5a (a warm wood pair that sits in the app's gold palette; Lichess' brown #f0d9b5 / #b58863 is the same family and proves Cburnett reads well on it).
  const CSS = `.ch{display:flex;flex-direction:column;gap:10px;color:#15233a;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
.ch button,.ch a{font:inherit;color:inherit;cursor:pointer;touch-action:manipulation}
.ch-st{font-size:14px;font-weight:600;text-align:center;min-height:20px}
/* the app column is 366 wide (338 inside the screen padding): bleed 9 px each side so the 8 squares stay 44 px, inside the column */
.ch-frame{padding:0;margin:0 -9px;border-radius:13px;background:rgba(255,255,255,.58);border:1px solid rgba(255,255,255,.7);box-sizing:border-box}
.ch-board{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));grid-template-rows:repeat(8,minmax(0,1fr));width:100%;aspect-ratio:1/1;border-radius:12px;overflow:hidden;box-sizing:border-box}
.ch-sq.mine{touch-action:none}
.ch-sq{border:0;padding:0;margin:0;position:relative;display:flex;align-items:center;justify-content:center;min-width:0;line-height:1;background-color:#f0e2c4;background-repeat:no-repeat}
.ch-sq.dk{background-color:#b88a5a}
.ch-sq.lm{background-image:linear-gradient(rgba(246,214,86,.6),rgba(246,214,86,.6))}
.ch-sq.sel{background-image:linear-gradient(rgba(246,214,86,.85),rgba(246,214,86,.85))}
.ch-sq.src .ch-pc{opacity:.3}
.ch-sq.chk::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at center,rgba(255,0,0,1) 0%,rgba(231,0,0,1) 25%,rgba(169,0,0,0) 89%,rgba(158,0,0,0) 100%);animation:chkp 1.1s ease-in-out infinite alternate}
@keyframes chkp{from{opacity:.65}to{opacity:1}}
.ch-pc{width:100%;height:100%;display:block;position:relative;z-index:1;pointer-events:none;padding:1px;box-sizing:border-box}
.ch-pc.ghost{position:absolute;inset:0;z-index:2}
.ch-sq i{position:absolute;z-index:3;width:30%;height:30%;border-radius:50%;background:rgba(20,85,30,.5);pointer-events:none}
.ch-sq i.cap{width:92%;height:92%;background:none;border:4px solid rgba(20,85,30,.45);box-sizing:border-box}
.ch-sq .co{position:absolute;z-index:2;font-size:12px;line-height:1;font-weight:700;pointer-events:none;color:#b88a5a}
.ch-sq.dk .co{color:#f0e2c4}
.ch-sq .co.r{top:2px;left:3px}.ch-sq .co.f{bottom:2px;right:3px}
.ch-sq:focus-visible{outline:3px solid #1f63b4;outline-offset:-3px}
.ch-drag{position:fixed;left:0;top:0;z-index:2147483000;pointer-events:none;will-change:transform}
.ch-drag .ch-pc{padding:0}
.ch-cap{display:flex;align-items:center;gap:6px;min-height:28px;font-size:12px;font-weight:600}
.ch-cap .who{white-space:nowrap}
.ch-cap .pcs{display:flex;align-items:center;flex:1;min-width:0;overflow:hidden}
.ch-cap .pcs svg{width:20px;height:20px;margin-right:-6px;flex:none;padding:0}
.ch-cap .adv{font-size:12px;font-weight:700;white-space:nowrap}
.ch-moves{display:flex;flex-wrap:wrap;gap:2px 8px;max-height:72px;overflow-y:auto;padding:6px 10px;border-radius:12px;background:rgba(255,255,255,.5);font-size:14px;font-weight:600;min-height:32px;box-sizing:border-box;align-items:center}
.ch-moves .n{opacity:.55}.ch-moves .m.last{background:rgba(246,214,86,.6);border-radius:6px;padding:0 4px}.ch-moves .none{opacity:.55;font-weight:500}
.ch-end{border-radius:16px;padding:14px;text-align:center;background:rgba(255,255,255,.7);border:1px solid rgba(255,255,255,.8);animation:chend .22s ease-out}
.ch-end b{display:block;font-size:24px;font-weight:700}.ch-end span{display:block;font-size:14px;margin:2px 0 10px}
@keyframes chend{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.ch-row{display:flex;gap:8px;flex-wrap:wrap}.ch-row>*{flex:1 1 auto}.ch-row.tight{gap:6px;flex-wrap:nowrap}.ch-row.tight .ch-btn{padding:0 4px;gap:4px;flex:1 1 0;min-width:0}.ch-btn svg{width:18px;height:18px;flex:none}
.ch-btn{border:0;border-radius:12px;padding:0 14px;min-height:44px;background:rgba(21,35,58,.08);font-weight:600;font-size:14px;display:inline-flex;align-items:center;justify-content:center;gap:6px;text-align:center;text-decoration:none;box-sizing:border-box}
.ch-btn.pri{background:rgba(21,35,58,.85);color:#fff}.ch-btn:disabled{opacity:.4}.ch-btn[aria-pressed="true"]{background:#f1e6cc}
.ch-pick{display:grid;grid-template-columns:1fr;gap:8px}.ch-pick .ch-btn{min-height:56px;font-size:16px}
.ch-promo{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.ch-promo .ch-btn{min-height:64px;font-size:12px;flex-direction:column;gap:0;padding:0 4px;background:rgba(240,226,196,.9)}.ch-promo .ch-pc{width:36px;height:36px}
.ch-note{font-size:12px;opacity:.65;text-align:center}
.ch h3{margin:2px 0 0;font-size:14px;opacity:.75;font-weight:700}
html[data-theme="dark"] :is(.ch-board,.ch-cap .pcs,.ch-drag,.ch-promo .ch-pc){filter:invert(1) hue-rotate(180deg)}
html[data-theme="dark"] .ch-sq.lm{background-image:linear-gradient(rgba(242,182,64,.7),rgba(242,182,64,.7))}html[data-theme="dark"] .ch-sq.sel{background-image:linear-gradient(rgba(242,182,64,.95),rgba(242,182,64,.95))}html[data-theme="dark"] .ch-sq.chk::before{background:radial-gradient(ellipse at center,rgb(232,79,0) 0%,rgb(232,60,0) 25%,rgba(200,40,0,0) 89%)}
@media (prefers-reduced-motion:reduce){.ch *,.ch *::before,.ch *::after{animation:none!important;transition:none!important}}`;

